{"content":""""Small statistics helpers."""


def mean(xs):
    """Return the arithmetic mean of ``xs`` as a float.

    An empty sequence has no mean, so 0.0 is returned instead.
    """
    xs = list(xs)
    if not xs:
        return 0.0
    return sum(xs) / len(xs)
